TEXT = TABLEAU_6 + "\f" + TABLEAU_11 + "\f" + TABLEAU_A11


class NigerReads(unittest.TestCase):
    def test_tables(self):
        table = nc.parse_departments(TEXT)
        self.assertEqual(table["regions"]["AGADEZ"], (251_257, 236_363, 487_620))
        self.assertEqual(table["departments"][("NIAMEY", "VILLE DE NIAMEY")],
                         (511_166, 515_682, 1_026_848))
        self.assertEqual(len(table["departments"]), 67)
        ages = nc.parse_ages(LAYOUT)
        self.assertEqual(ages["ZINDER"][0], (0, 4, (411_256, 392_353, 803_609)))
        self.assertEqual(ages["NIAMEY"][-1][2], (511_166, 515_682, 1_026_848))
        religion = nc.parse_religion(TEXT)
        self.assertEqual(religion["MARADI"]["Islam"], 3_379_780)
        nc.check(table, ages, religion)
        self.assertEqual(nc.median_of(["AGADEZ"], ages), 15.9)
        self.assertEqual(nc.parse_published_medians(TEXT)["MARADI"], 13)

    def test_build(self):
        records, report = nc.build(TEXT, LAYOUT, ADMIN1, ADMIN2)
        self.assertEqual(report, [])
        self.assertEqual(len(records), 6 + 67)
        by = {(r["level"], r["name"]): r for r in records}
        merged = by[("admin1", "Tahoua/Agadez")]
        men, women = 1_660_934 + 251_257, 1_667_431 + 236_363
        self.assertEqual(merged["sex_ratio"]["value"], round(1000 * men / women))
        self.assertIn("together", merged["median_age_note"])
        self.assertEqual(by[("admin1", "Niamey")]["religion"][0]["group"], "Islam")
        self.assertIn("Tahoua and Agadez", merged["capital"]["note"])
        # The capital district is the city, which is its capital, cited.
        niamey = by[("admin1", "Niamey")]
        self.assertEqual(niamey["capital"], "Niamey")
        self.assertIn("capital", niamey["sources"][0]["field"].split("/"))
        self.assertNotIn("note", by[("admin1", "Maradi")]["capital"])
        # Tableau A 11 has "Sans religion" and "ND" apart: the note says which
        # is shown as not stated.
        self.assertIn("not declared (ND) are shown as not stated", niamey["religion_note"])
        self.assertNotIn("gave none", niamey["religion_note"])
        city = by[("admin2", "Tahoua Ville")]
        self.assertEqual(city["sex_ratio"]["value"], round(1000 * 74_096 / 75_402))


if __name__ == "__main__":
    unittest.main()
